const HOLD = H => '';
const J = (G, D, H, F, e, T, eff) => R`${G} ; ${D} \vdash^{${H ? R`${F} ${h('tj.held', R`\triangleleft`)} ${H}` : F}} ${e} : ${T}\annot{\ ${h('tj.eff', '!')}\ ${eff}}`;
